const intro=(title,bubble,name,lead)=>({title,bubble,kind:'intro',name,lead});
const single=(title,bubble,question,answers,correct,ok,bad,badByAnswer)=>({title,bubble,kind:'question',selection:'single',question,answers,correct,ok,bad,...(badByAnswer?{badByAnswer}:{})});
const clues=(title,bubble,question,answers,correctSet,ok,bad)=>({title,bubble,kind:'question',selection:'multiple',question,answers,correctSet,ok,bad});
const pause=(title,bubble,text)=>({title,bubble,kind:'pause',text});
const finale=(title,bubble,rule,discussion,source='')=>({title,bubble,kind:'final',rule,discussion,source});

