function normalizeMission(mission,id){
 const category=mission.category.includes('Социальная')?'social':'digital';
 return {
  id,
  slug:`mission-${String(id).padStart(2,'0')}`,
  title:mission.name,
  category,
  categoryLabel:mission.category,
  duration:'5–10 минут',
  version:'2026.09',
  slides:mission.slides.map((slide,index)=>({...slide,id:index+1,image:`assets/${mission.imageBase}/page-${index+1}.webp`}))
 };
}

export const MISSIONS=[
 normalizeMission(FIRST_MISSION,1),
 ...Object.entries(KIBER_MISSIONS).map(([id,mission])=>normalizeMission(mission,Number(id)))
];

export function validateMissionCatalog(missions){
 const invalidMissions=missions.filter((mission)=>{
  const questionCount=mission.slides.filter((slide)=>slide.kind==='question').length;
  return mission.slides.length!==8||questionCount!==5||!mission.slides.every((slide)=>slide.image);
 }).map((mission)=>mission.id);
 return {
  missionCount:missions.length,
  socialCount:missions.filter((mission)=>mission.category==='social').length,
  digitalCount:missions.filter((mission)=>mission.category==='digital').length,
  invalidMissions
 };
}
